// REQ-AUTOUPDATE: -1 nothing yet, 1000 being handed over, else PackageInstaller's status (0 = success)
private volatile int olUpdateStatus = -1;
private android.content.BroadcastReceiver olUpdateReceiver = null;

public boolean AndroidThunkJava_OLUpdate_CanInstall()
{
	return getPackageManager().canRequestPackageInstalls();
}

public void AndroidThunkJava_OLUpdate_OpenAllow()
{
	try
	{
		startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
			android.net.Uri.parse("package:" + getPackageName())));
	}
	catch (Throwable t)
	{
		android.util.Log.w("OLUPD", "the unknown apps page did not open: " + t);
	}
}

public int AndroidThunkJava_OLUpdate_Status()
{
	return olUpdateStatus;
}

public void AndroidThunkJava_OLUpdate_Install(final String apkPath)
{
	olUpdateStatus = 1000;
	final android.content.Context ctx = getApplicationContext();
	final String action = getPackageName() + ".OLUPDATE_STATUS";
	if (olUpdateReceiver == null)
	{
		olUpdateReceiver = new android.content.BroadcastReceiver()
		{
			@Override
			public void onReceive(android.content.Context c, Intent intent)
			{
				int status = intent.getIntExtra(android.content.pm.PackageInstaller.EXTRA_STATUS, -999);
				android.util.Log.i("OLUPD", "install status " + status + ": " + intent.getStringExtra(android.content.pm.PackageInstaller.EXTRA_STATUS_MESSAGE));
				if (status == android.content.pm.PackageInstaller.STATUS_PENDING_USER_ACTION)
				{
					Intent confirm = (Intent) intent.getParcelableExtra(Intent.EXTRA_INTENT);
					if (confirm != null)
					{
						confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
						c.startActivity(confirm);
					}
					return;
				}
				olUpdateStatus = status;
			}
		};
		ctx.registerReceiver(olUpdateReceiver, new android.content.IntentFilter(action));
	}
	new Thread(new Runnable()
	{
		@Override
		public void run()
		{
			try
			{
				java.io.File apk = new java.io.File(apkPath);
				android.content.pm.PackageInstaller pi = ctx.getPackageManager().getPackageInstaller();
				android.content.pm.PackageInstaller.SessionParams p = new android.content.pm.PackageInstaller.SessionParams(
					android.content.pm.PackageInstaller.SessionParams.MODE_FULL_INSTALL);
				p.setAppPackageName(ctx.getPackageName());
				p.setSize(apk.length());
				int id = pi.createSession(p);
				android.content.pm.PackageInstaller.Session s = pi.openSession(id);
				java.io.InputStream in = new java.io.FileInputStream(apk);
				java.io.OutputStream out = s.openWrite("update.apk", 0, apk.length());
				byte[] buf = new byte[65536];
				int n;
				while ((n = in.read(buf)) > 0)
				{
					out.write(buf, 0, n);
				}
				s.fsync(out);
				out.close();
				in.close();
				Intent cb = new Intent(action).setPackage(ctx.getPackageName());
				int flags = android.app.PendingIntent.FLAG_UPDATE_CURRENT;
				if (android.os.Build.VERSION.SDK_INT >= 31)
				{
					flags |= android.app.PendingIntent.FLAG_MUTABLE;      // (the installer fills in the status)
				}
				s.commit(android.app.PendingIntent.getBroadcast(ctx, id, cb, flags).getIntentSender());
				s.close();
			}
			catch (Throwable t)
			{
				android.util.Log.w("OLUPD", "the install did not start: " + t);
				olUpdateStatus = 9999;
			}
		}
	}, "olupdate-install").start();
}

// REQ-DROPJAVA: the receiver the manifest names, generated here as a nested class so public source builds complete
// (it used to be Build/Android/src/.../OutlawsUpdateReplaced.java, which the public tree leaves out). It reaches the
// new version after the game has updated itself and brings it up; the VR category is what starts it in the headset,
// not as a flat panel, and if Android holds the start back the player just opens the game from the library.
public static class OutlawsUpdateReplaced extends android.content.BroadcastReceiver
{
	@Override
	public void onReceive(android.content.Context ctx, Intent intent)
	{
		Intent start = ctx.getPackageManager().getLaunchIntentForPackage(ctx.getPackageName());
		if (start == null)
		{
			return;
		}
		start.addCategory("com.oculus.intent.category.VR");
		start.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
		try
		{
			ctx.startActivity(start);
		}
		catch (Throwable t)
		{
			android.util.Log.w("OLUPD", "the relaunch did not start: " + t);
		}
	}
}
